package com.queueless.controller;
import com.queueless.dao.QueueDAO; import com.queueless.model.QueueEntry; import com.queueless.util.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*;
@WebServlet("/api/register") public class RegisterServlet extends HttpServlet{
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{String name=req.getParameter("name"),phone=req.getParameter("phone"),sid=req.getParameter("serviceId"),type=req.getParameter("registrationType");try{if(name==null||name.trim().length()<2)throw new IllegalArgumentException("Please enter a valid name.");if(phone==null||!phone.matches("[0-9+() -]{8,20}"))throw new IllegalArgumentException("Please enter a valid phone number.");long serviceId=Long.parseLong(sid);if(!"PHYSICAL".equals(type))type="ONLINE";QueueEntry q=new QueueDAO().register(name.trim(),phone.trim(),serviceId,type);if("text/html".equalsIgnoreCase(req.getHeader("Accept"))){req.setAttribute("entry",q);req.getRequestDispatcher("/token.jsp").forward(req,res);return;}res.setContentType("application/json;charset=UTF-8");res.getWriter().write("{\"success\":true,\"id\":\""+q.id+"\",\"token\":\""+q.token+"\",\"service\":\""+JsonUtil.esc(q.serviceName)+"\",\"serviceId\":\""+q.serviceId+"\",\"status\":\""+q.status+"\"}");}catch(NumberFormatException e){send(res,400,"Please select a valid service.");}catch(IllegalArgumentException e){send(res,400,e.getMessage());}catch(Exception e){send(res,500,"Registration could not be completed. Please try again.");}}
 private void send(HttpServletResponse r,int code,String m)throws IOException{r.setStatus(code);r.setContentType("application/json;charset=UTF-8");r.getWriter().write(JsonUtil.error(m));}
}
